<template>
  <div class="page">
    <div class="goods-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>商品管理</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="name" label="商品名称" min-width="180" />
            <el-table-column prop="price" label="价格" min-width="120" />
            <el-table-column prop="category" label="分类" min-width="120" />
            <el-table-column prop="stock" label="库存" min-width="100" />
            <el-table-column prop="sales" label="销量" min-width="100" />
            <el-table-column prop="tag" label="状态" min-width="100">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createtime" label="上架时间" min-width="180" />
            <el-table-column label="操作" min-width="140">
              <template #default="scope">
                <el-button
                  size="small"
                  :type="scope.row.tag === '已下架' ? 'success' : 'danger'"
                  @click="handleToggle(scope.row.name)"
                >
                  {{ scope.row.tag === '已下架' ? '上架' : '下架' }}
                </el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="goods-manage__pagination-wrap">
        <div class="totalnum">
          <h3>商品统计</h3>
          <p>当前共 {{ tableData.length }} 个商品</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import { ElMessage } from 'element-plus'

const currentPage = ref(1)
const pageSize = ref(6)

const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

const tagType = (tag) => {
  const map = {
    '在售': 'success',
    '已下架': 'danger',
    '售罄': 'warning',
  }
  return map[tag] || 'info'
}

const handleToggle = (name) => {
  const row = tableData.value.find((item) => item.name === name)
  if (!row) return
  row.tag = row.tag === '已下架' ? '在售' : '已下架'
  ElMessage.success(`商品「${name}」已${row.tag === '在售' ? '上架' : '下架'}`)
}

const tableData = ref([
